// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.20;

import "../interfaces/IKYCVerifier.sol";

/**
 * @title KYCLib
 * @notice Library for KYC verification logic
 */
library KYCLib {
    error InvalidKYCProof();
    error KYCLevelTooLow(uint8 required, uint8 provided);
    error KYCExpired();
    error CountryRestricted(uint16 countryCode);

    struct KYCProof {
        uint8 level;
        uint16 countryCode;
        uint256 expiry;
        bytes signature;
    }

    function verifyKYCProof(
        address _kycVerifier,
        address _user,
        KYCProof calldata _proof,
        uint8 _minLevel,
        uint16[] storage _defaultRestrictedCountries,
        mapping(uint256 => mapping(uint16 => bool)) storage _deploymentRestrictedCountries,
        uint256 _deploymentId
    ) internal view {
        if (_kycVerifier == address(0)) {
            return;
        }

        IKYCVerifier verifier = IKYCVerifier(_kycVerifier);

        bool valid = verifier.verify(
            _user,
            _proof.level,
            _proof.countryCode,
            _proof.expiry,
            _proof.signature
        );

        if (!valid) revert InvalidKYCProof();
        if (_proof.level < _minLevel) revert KYCLevelTooLow(_minLevel, _proof.level);
        if (block.timestamp > _proof.expiry) revert KYCExpired();

        if (isCountryRestricted(
            _proof.countryCode,
            _deploymentId,
            _defaultRestrictedCountries,
            _deploymentRestrictedCountries
        )) {
            revert CountryRestricted(_proof.countryCode);
        }
    }

    function isCountryRestricted(
        uint16 _countryCode,
        uint256 _deploymentId,
        uint16[] storage _defaultRestrictedCountries,
        mapping(uint256 => mapping(uint16 => bool)) storage _deploymentRestrictedCountries
    ) internal view returns (bool) {
        if (_deploymentId > 0 && _deploymentRestrictedCountries[_deploymentId][_countryCode]) {
            return true;
        }

        uint256 length = _defaultRestrictedCountries.length;
        for (uint256 i = 0; i < length; ++i) {
            if (_defaultRestrictedCountries[i] == _countryCode) {
                return true;
            }
        }

        return false;
    }
}

contracts/tokenize/RWATokenizationFactor.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";
import "./KYCLib.sol";

interface IModularCompliance {
    function bindToken(address _token) external;
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
}

interface IRWAERC3643 {
    function mint(address _to, uint256 _amount) external;
    function grantRole(bytes32 role, address account) external;
    function renounceRole(bytes32 role, address account) external;
    function hasRole(bytes32 role, address account) external view returns (bool);
    function setMinKYCLevel(uint8 _level) external;
    function setKYCEnforced(bool _enforced) external;
    function compliance() external view returns (address);
}

/**
 * @title RWATokenizationFactory
 * @notice Factory for RWA tokenization with off-chain KYC
 */
contract RWATokenizationFactory is 
    Initializable, 
    UUPSUpgradeable, 
    OwnableUpgradeable, 
    PausableUpgradeable, 
    ReentrancyGuardUpgradeable 
{
    using KYCLib for *;

    struct Implementations {
        address securityToken;
        address projectNFT;
        address compliance;
        address tradeEscrow;
        address dividendDistributor;
    }

    struct TokenDeployment {
        uint256 deploymentId;
        address owner;
        address securityToken;
        address projectNFT;
        address tradeEscrow;
        address dividendDistributor;
        DeploymentType deploymentType;
        uint256 deployedAt;
        bool active;
        string metadataURI;
        uint8 minKYCLevel;
    }

    enum DeploymentType { TOKEN_ONLY, NFT_ONLY, NFT_AND_TOKEN, NFT_TOKEN_ESCROW }

    // RWASecurityToken roles. The factory holds them only while a deployment is in progress.
    bytes32 private constant DEFAULT_ADMIN_ROLE = 0x00;
    bytes32 private constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 private constant BURNER_ROLE = keccak256("BURNER_ROLE");
    bytes32 private constant COMPLIANCE_ROLE = keccak256("COMPLIANCE_ROLE");
    bytes32 private constant SNAPSHOT_ROLE = keccak256("SNAPSHOT_ROLE");
    bytes32 private constant AGENT_ROLE = keccak256("AGENT_ROLE");
    bytes32 private constant RECOVERY_ROLE = keccak256("RECOVERY_ROLE");

    Implementations public implementations;
    address public kycVerifier;
    address public platformFeeRecipient;
    uint256 public escrowTransactionFeeBps;
    uint256 public deploymentCounter;
    
    mapping(uint256 => TokenDeployment) public deployments;
    mapping(address => uint256[]) public ownerDeployments;
    mapping(address => bool) public approvedDeployers;
    mapping(uint256 => mapping(uint16 => bool)) public deploymentRestrictedCountries;
    uint16[] public defaultRestrictedCountries;
    
    bool public requireApproval;
    bool public requireKYCForDeployment;
    uint8 public minKYCLevelForDeployment;

    // ============ v2 storage (appended) ============
    /// @notice Stablecoin that trade escrows settle in; required to deploy one
    address public escrowStablecoin;

    event TokenDeployed(uint256 indexed deploymentId, address indexed owner, address securityToken, uint256 supply, DeploymentType deploymentType, uint8 minKYCLevel);
    event ProjectNFTDeployed(uint256 indexed deploymentId, address indexed owner, address projectNFT, DeploymentType deploymentType);
    event EscrowDeployed(uint256 indexed deploymentId, address indexed owner, address tradeEscrow);
    event DividendModuleDeployed(uint256 indexed deploymentId, address indexed owner, address dividendDistributor);
    event ImplementationUpdated(string contractType, address indexed oldImpl, address indexed newImpl);
    event DeployerApprovalUpdated(address indexed deployer, bool approved);
    event DeploymentDeactivated(uint256 indexed deploymentId);
    event KYCVerifierUpdated(address indexed oldVerifier, address indexed newVerifier);
    event EscrowStablecoinUpdated(address indexed oldStablecoin, address indexed newStablecoin);
    event TokenReleasedToIssuer(uint256 indexed deploymentId, address indexed securityToken, address indexed issuer);

    error InvalidAddress();
    error DeployerNotApproved();
    error DeploymentNotFound();
    error NotDeploymentOwner();
    error InvalidSupply();
    error AlreadyHasModule();
    error InvalidKYCLevel();

    modifier onlyApprovedDeployer() {
        if (requireApproval && !approvedDeployers[msg.sender] && msg.sender != owner()) {
            revert DeployerNotApproved();
        }
        _;
    }

    function initialize(
        address _admin,
        address _securityTokenImpl,
        address _projectNFTImpl,
        address _complianceImpl,
        address _kycVerifier,
        address _feeRecipient
    ) external initializer {
        if (_admin == address(0) || _securityTokenImpl == address(0) || 
            _complianceImpl == address(0) || _kycVerifier == address(0) ||
            _feeRecipient == address(0)) revert InvalidAddress();

        __Ownable_init();
        __UUPSUpgradeable_init();
        __Pausable_init();
        __ReentrancyGuard_init();
        _transferOwnership(_admin);

        implementations = Implementations({
            securityToken: _securityTokenImpl,
            projectNFT: _projectNFTImpl,
            compliance: _complianceImpl,
            tradeEscrow: address(0),
            dividendDistributor: address(0)
        });

        kycVerifier = _kycVerifier;
        platformFeeRecipient = _feeRecipient;
        escrowTransactionFeeBps = 100;
        requireApproval = true;

        defaultRestrictedCountries.push(408);
        defaultRestrictedCountries.push(364);
        defaultRestrictedCountries.push(760);
        defaultRestrictedCountries.push(192);
    }

    function _authorizeUpgrade(address) internal override onlyOwner {}

    // ============ Deploy Functions (4-param, no KYC) ============

    function deployToken(string calldata _name, string calldata _symbol, uint256 _supply, string calldata _metadataURI
    ) external nonReentrant whenNotPaused onlyApprovedDeployer returns (uint256 deploymentId, address securityToken) {
        if (requireKYCForDeployment) revert KYCLib.KYCLevelTooLow(minKYCLevelForDeployment, 0);
        return _deployToken(_name, _symbol, _supply, _metadataURI, 1);
    }

    function deployProjectNFT(string calldata _name, string calldata _symbol, string calldata _metadataURI
    ) external nonReentrant whenNotPaused onlyApprovedDeployer returns (uint256 deploymentId, address projectNFT) {
        if (requireKYCForDeployment) revert KYCLib.KYCLevelTooLow(minKYCLevelForDeployment, 0);
        return _deployProjectNFTOnly(_name, _symbol, _metadataURI);
    }

    function deployNFTAndToken(string calldata _name, string calldata _symbol, uint256 _supply, string calldata _metadataURI
    ) external nonReentrant whenNotPaused onlyApprovedDeployer returns (uint256 deploymentId, address securityToken, address projectNFT) {
        if (requireKYCForDeployment) revert KYCLib.KYCLevelTooLow(minKYCLevelForDeployment, 0);
        return _deployNFTAndToken(_name, _symbol, _supply, _metadataURI, 1);
    }

    function deployWithEscrow(string calldata _name, string calldata _symbol, uint256 _supply, string calldata _metadataURI
    ) external nonReentrant whenNotPaused onlyApprovedDeployer returns (uint256 deploymentId, address securityToken, address projectNFT, address tradeEscrow) {
        if (requireKYCForDeployment) revert KYCLib.KYCLevelTooLow(minKYCLevelForDeployment, 0);
        return _deployWithEscrow(_name, _symbol, _supply, _metadataURI, 1);
    }

    // ============ Deploy Functions (6-param, with KYC) ============

    function deployNFTAndTokenWithKYC(
        string calldata _name, string calldata _symbol, uint256 _supply, string calldata _metadataURI,
        uint8 _minKYCLevel, KYCLib.KYCProof calldata _kycProof
    ) external nonReentrant whenNotPaused onlyApprovedDeployer returns (uint256 deploymentId, address securityToken, address projectNFT) {
        if (requireKYCForDeployment) {
            KYCLib.verifyKYCProof(kycVerifier, msg.sender, _kycProof, minKYCLevelForDeployment, defaultRestrictedCountries, deploymentRestrictedCountries, 0);
        }
        if (_minKYCLevel > 4) revert InvalidKYCLevel();
        return _deployNFTAndToken(_name, _symbol, _supply, _metadataURI, _minKYCLevel);
    }

    function deployWithEscrowAndKYC(
        string calldata _name, string calldata _symbol, uint256 _supply, string calldata _metadataURI,
        uint8 _minKYCLevel, KYCLib.KYCProof calldata _kycProof
    ) external nonReentrant whenNotPaused onlyApprovedDeployer returns (uint256 deploymentId, address securityToken, address projectNFT, address tradeEscrow) {
        if (requireKYCForDeployment) {
            KYCLib.verifyKYCProof(kycVerifier, msg.sender, _kycProof, minKYCLevelForDeployment, defaultRestrictedCountries, deploymentRestrictedCountries, 0);
        }
        if (_minKYCLevel > 4) revert InvalidKYCLevel();
        return _deployWithEscrow(_name, _symbol, _supply, _metadataURI, _minKYCLevel);
    }

    // ============ Internal Deployment ============

    function _deployToken(string calldata _name, string calldata _symbol, uint256 _supply, string calldata _metadataURI, uint8 _minKYCLevel
    ) internal returns (uint256 deploymentId, address securityToken) {
        if (_supply == 0) revert InvalidSupply();
        deploymentId = deploymentCounter++;
        address compliance = _deployCompliance();
        securityToken = _deploySecurityToken(_name, _symbol, _supply, compliance, _minKYCLevel);
        _issueAndHandOver(securityToken, compliance, msg.sender, _supply);

        deployments[deploymentId] = TokenDeployment(deploymentId, msg.sender, securityToken, address(0), address(0), address(0), DeploymentType.TOKEN_ONLY, block.timestamp, true, _metadataURI, _minKYCLevel);
        ownerDeployments[msg.sender].push(deploymentId);
        emit TokenDeployed(deploymentId, msg.sender, securityToken, _supply, DeploymentType.TOKEN_ONLY, _minKYCLevel);
    }

    function _deployProjectNFTOnly(string calldata _name, string calldata _symbol, string calldata _metadataURI
    ) internal returns (uint256 deploymentId, address projectNFT) {
        deploymentId = deploymentCounter++;
        projectNFT = _deployProjectNFT(_name, _symbol);
        deployments[deploymentId] = TokenDeployment(deploymentId, msg.sender, address(0), projectNFT, address(0), address(0), DeploymentType.NFT_ONLY, block.timestamp, true, _metadataURI, 0);
        ownerDeployments[msg.sender].push(deploymentId);
        emit ProjectNFTDeployed(deploymentId, msg.sender, projectNFT, DeploymentType.NFT_ONLY);
    }

    function _deployNFTAndToken(string calldata _name, string calldata _symbol, uint256 _supply, string calldata _metadataURI, uint8 _minKYCLevel
    ) internal returns (uint256 deploymentId, address securityToken, address projectNFT) {
        if (_supply == 0) revert InvalidSupply();
        deploymentId = deploymentCounter++;
        address compliance = _deployCompliance();
        securityToken = _deploySecurityToken(_name, _symbol, _supply, compliance, _minKYCLevel);
        projectNFT = _deployProjectNFT(string(abi.encodePacked(_name, " Project")), string(abi.encodePacked(_symbol, "PRJ")));
        _issueAndHandOver(securityToken, compliance, msg.sender, _supply);

        deployments[deploymentId] = TokenDeployment(deploymentId, msg.sender, securityToken, projectNFT, address(0), address(0), DeploymentType.NFT_AND_TOKEN, block.timestamp, true, _metadataURI, _minKYCLevel);
        ownerDeployments[msg.sender].push(deploymentId);
        emit TokenDeployed(deploymentId, msg.sender, securityToken, _supply, DeploymentType.NFT_AND_TOKEN, _minKYCLevel);
        emit ProjectNFTDeployed(deploymentId, msg.sender, projectNFT, DeploymentType.NFT_AND_TOKEN);
    }

    function _deployWithEscrow(string calldata _name, string calldata _symbol, uint256 _supply, string calldata _metadataURI, uint8 _minKYCLevel
    ) internal returns (uint256 deploymentId, address securityToken, address projectNFT, address tradeEscrow) {
        if (_supply == 0) revert InvalidSupply();
        if (implementations.tradeEscrow == address(0)) revert InvalidAddress();
        deploymentId = deploymentCounter++;
        address compliance = _deployCompliance();
        securityToken = _deploySecurityToken(_name, _symbol, _supply, compliance, _minKYCLevel);
        projectNFT = _deployProjectNFT(string(abi.encodePacked(_name, " Project")), string(abi.encodePacked(_symbol, "PRJ")));
        tradeEscrow = _deployTradeEscrow(securityToken);
        _issueAndHandOver(securityToken, compliance, msg.sender, _supply);

        deployments[deploymentId] = TokenDeployment(deploymentId, msg.sender, securityToken, projectNFT, tradeEscrow, address(0), DeploymentType.NFT_TOKEN_ESCROW, block.timestamp, true, _metadataURI, _minKYCLevel);
        ownerDeployments[msg.sender].push(deploymentId);
        emit TokenDeployed(deploymentId, msg.sender, securityToken, _supply, DeploymentType.NFT_TOKEN_ESCROW, _minKYCLevel);
        emit ProjectNFTDeployed(deploymentId, msg.sender, projectNFT, DeploymentType.NFT_TOKEN_ESCROW);
        emit EscrowDeployed(deploymentId, msg.sender, tradeEscrow);
    }

    // ============ Internal Helpers ============

    function _deployCompliance() internal returns (address) {
        return address(new ERC1967Proxy(implementations.compliance, abi.encodeWithSignature("initialize(address)", address(this))));
    }

    function _deploySecurityToken(string calldata _name, string calldata _symbol, uint256 _maxSupply, address _compliance, uint8 _minKYCLevel) internal returns (address) {
        address token = address(new ERC1967Proxy(implementations.securityToken, abi.encodeWithSignature("initialize(string,string,address,address,address,uint256)", _name, _symbol, address(this), _compliance, kycVerifier, _maxSupply)));
        IModularCompliance(_compliance).bindToken(token);
        IRWAERC3643(token).setMinKYCLevel(_minKYCLevel);
        return token;
    }

    function _deployProjectNFT(string memory _name, string memory _symbol) internal returns (address) {
        return address(new ERC1967Proxy(implementations.projectNFT, abi.encodeWithSignature("initialize(string,string,address)", _name, _symbol, msg.sender)));
    }

    function _deployTradeEscrow(address _securityToken) internal returns (address) {
        if (escrowStablecoin == address(0)) revert InvalidAddress();
        return address(new ERC1967Proxy(implementations.tradeEscrow, abi.encodeWithSignature(
            "initialize(address,address,address,address,address,uint256)",
            msg.sender, _securityToken, escrowStablecoin, kycVerifier, platformFeeRecipient, escrowTransactionFeeBps
        )));
    }

    /// @dev Mints the initial supply to the issuer, gives the issuer every token role and the
    ///      compliance contract, and drops all of the factory's own powers over both.
    ///      The initial issuance is the one mint that skips the holder KYC check: the issuer ends up
    ///      with DEFAULT_ADMIN_ROLE (and could switch enforcement off anyway), and enforcement is
    ///      back on before this function returns.
    function _issueAndHandOver(address _token, address _compliance, address _issuer, uint256 _supply) internal {
        IRWAERC3643 token = IRWAERC3643(_token);
        token.setKYCEnforced(false);
        token.mint(_issuer, _supply);
        token.setKYCEnforced(true);

        bytes32[6] memory roles = [MINTER_ROLE, BURNER_ROLE, COMPLIANCE_ROLE, SNAPSHOT_ROLE, AGENT_ROLE, RECOVERY_ROLE];
        token.grantRole(DEFAULT_ADMIN_ROLE, _issuer);
        for (uint256 i = 0; i < roles.length; i++) {
            token.grantRole(roles[i], _issuer);
            token.renounceRole(roles[i], address(this));
        }
        token.renounceRole(DEFAULT_ADMIN_ROLE, address(this));

        IModularCompliance(_compliance).transferOwnership(_issuer);
    }

    /// @notice Drop the operational roles and the compliance ownership the factory kept on tokens it
    ///         deployed before this version (it only gave up DEFAULT_ADMIN_ROLE then). Compliance
    ///         ownership goes to the deployment owner. Idempotent.
    function releaseLegacyToken(uint256 _deploymentId) external nonReentrant {
        TokenDeployment storage d = deployments[_deploymentId];
        if (d.owner == address(0)) revert DeploymentNotFound();
        if (msg.sender != d.owner && msg.sender != owner()) revert NotDeploymentOwner();
        if (d.securityToken == address(0)) revert InvalidAddress();

        IRWAERC3643 token = IRWAERC3643(d.securityToken);
        bytes32[6] memory roles = [MINTER_ROLE, BURNER_ROLE, COMPLIANCE_ROLE, SNAPSHOT_ROLE, AGENT_ROLE, RECOVERY_ROLE];
        for (uint256 i = 0; i < roles.length; i++) {
            if (token.hasRole(roles[i], address(this))) token.renounceRole(roles[i], address(this));
        }
        IModularCompliance compliance = IModularCompliance(token.compliance());
        if (compliance.owner() == address(this)) compliance.transferOwnership(d.owner);

        emit TokenReleasedToIssuer(_deploymentId, d.securityToken, d.owner);
    }

    // ============ Add Modules ============

    function addEscrow(uint256 _deploymentId) external nonReentrant whenNotPaused returns (address tradeEscrow) {
        TokenDeployment storage d = deployments[_deploymentId];
        if (d.owner == address(0)) revert DeploymentNotFound();
        if (d.owner != msg.sender) revert NotDeploymentOwner();
        if (d.securityToken == address(0) || d.tradeEscrow != address(0)) revert AlreadyHasModule();
        if (implementations.tradeEscrow == address(0)) revert InvalidAddress();
        tradeEscrow = _deployTradeEscrow(d.securityToken);
        d.tradeEscrow = tradeEscrow;
        emit EscrowDeployed(_deploymentId, msg.sender, tradeEscrow);
    }

    function addDividendModule(uint256 _deploymentId) external nonReentrant whenNotPaused returns (address dividendDistributor) {
        TokenDeployment storage d = deployments[_deploymentId];
        if (d.owner == address(0)) revert DeploymentNotFound();
        if (d.owner != msg.sender) revert NotDeploymentOwner();
        if (d.securityToken == address(0) || d.dividendDistributor != address(0)) revert AlreadyHasModule();
        if (implementations.dividendDistributor == address(0)) revert InvalidAddress();
        dividendDistributor = address(new ERC1967Proxy(implementations.dividendDistributor, abi.encodeWithSignature("initialize(address,address,address)", d.securityToken, msg.sender, platformFeeRecipient)));
        d.dividendDistributor = dividendDistributor;
        emit DividendModuleDeployed(_deploymentId, msg.sender, dividendDistributor);
    }

    // ============ Admin Functions ============

    function setSecurityTokenImplementation(address _impl) external onlyOwner { if (_impl == address(0)) revert InvalidAddress(); emit ImplementationUpdated("SecurityToken", implementations.securityToken, _impl); implementations.securityToken = _impl; }
    function setProjectNFTImplementation(address _impl) external onlyOwner { if (_impl == address(0)) revert InvalidAddress(); emit ImplementationUpdated("ProjectNFT", implementations.projectNFT, _impl); implementations.projectNFT = _impl; }
    function setComplianceImplementation(address _impl) external onlyOwner { if (_impl == address(0)) revert InvalidAddress(); emit ImplementationUpdated("Compliance", implementations.compliance, _impl); implementations.compliance = _impl; }
    function setTradeEscrowImplementation(address _impl) external onlyOwner { if (_impl == address(0)) revert InvalidAddress(); emit ImplementationUpdated("TradeEscrow", implementations.tradeEscrow, _impl); implementations.tradeEscrow = _impl; }
    function setDividendDistributorImplementation(address _impl) external onlyOwner { if (_impl == address(0)) revert InvalidAddress(); emit ImplementationUpdated("DividendDistributor", implementations.dividendDistributor, _impl); implementations.dividendDistributor = _impl; }
    function setKYCVerifier(address _v) external onlyOwner { if (_v == address(0)) revert InvalidAddress(); emit KYCVerifierUpdated(kycVerifier, _v); kycVerifier = _v; }
    function setEscrowTransactionFee(uint256 _feeBps) external onlyOwner { require(_feeBps <= 1000, "Max 10%"); escrowTransactionFeeBps = _feeBps; }
    function setPlatformFeeRecipient(address _r) external onlyOwner { if (_r == address(0)) revert InvalidAddress(); platformFeeRecipient = _r; }
    function setEscrowStablecoin(address _s) external onlyOwner { if (_s == address(0)) revert InvalidAddress(); emit EscrowStablecoinUpdated(escrowStablecoin, _s); escrowStablecoin = _s; }
    function setRequireApproval(bool _r) external onlyOwner { requireApproval = _r; }
    function setDeployerApproval(address _d, bool _a) external onlyOwner { if (_d == address(0)) revert InvalidAddress(); approvedDeployers[_d] = _a; emit DeployerApprovalUpdated(_d, _a); }
    function deactivateDeployment(uint256 _id) external onlyOwner { if (deployments[_id].owner == address(0)) revert DeploymentNotFound(); deployments[_id].active = false; emit DeploymentDeactivated(_id); }
    function setKYCRequirement(bool _r, uint8 _l) external onlyOwner { if (_l > 4) revert InvalidKYCLevel(); requireKYCForDeployment = _r; minKYCLevelForDeployment = _l; }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    // ============ View Functions ============

    function getDeployment(uint256 _id) external view returns (TokenDeployment memory) { return deployments[_id]; }
    function getOwnerDeployments(address _o) external view returns (uint256[] memory) { return ownerDeployments[_o]; }
    function getOwnerDeploymentCount(address _o) external view returns (uint256) { return ownerDeployments[_o].length; }
    function getImplementations() external view returns (Implementations memory) { return implementations; }
    function isDeployerApproved(address _d) external view returns (bool) { return !requireApproval || approvedDeployers[_d] || _d == owner(); }
    function getKYCVerifier() external view returns (address) { return kycVerifier; }
    function getDefaultRestrictedCountries() external view returns (uint16[] memory) { return defaultRestrictedCountries; }

    receive() external payable {}
}

contracts/tokenize/RWATradeEscrow.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "../interfaces/IKYCVerifier.sol";

/**
 * @title RWATradeEscrow
 * @notice Escrow contract for P2P trading of security tokens with stablecoin settlement
 * @dev Uses off-chain KYC verification via KYCVerifier for compliance
 */
contract RWATradeEscrow is 
    Initializable,
    UUPSUpgradeable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable
{
    using SafeERC20 for IERC20;

    // ============ Structs ============

    struct Trade {
        uint256 tradeId;
        address seller;
        address buyer;
        uint256 tokenAmount;
        uint256 stableAmount;
        uint256 pricePerToken;
        uint256 createdAt;
        uint256 expiresAt;
        TradeStatus status;
        bool sellerDeposited;
        bool buyerDeposited;
        uint8 minKYCLevel;          // Minimum KYC level required for this trade
        uint16 sellerCountryCode;   // Seller's country (for compliance tracking)
    }

    struct KYCProof {
        uint8 level;
        uint16 countryCode;
        uint256 expiry;
        bytes signature;
    }
    
    struct CachedKYC {
        uint8 level;
        uint16 countryCode;
        uint256 expiry;
        uint256 cachedAt;
    }

    enum TradeStatus {
        CREATED,
        SELLER_DEPOSITED,
        BUYER_DEPOSITED,
        COMPLETED,
        CANCELLED,
        EXPIRED,
        DISPUTED
    }

    // ============ State Variables ============

    IERC20 public securityToken;
    IERC20 public stablecoin;
    IKYCVerifier public kycVerifier;
    address public platformFeeRecipient;
    
    uint256 public platformFeeBps;          // Default 100 = 1%
    uint256 public tradeCounter;
    uint256 public defaultExpirationTime;   // Default 24 hours
    
    mapping(uint256 => Trade) public trades;
    mapping(address => uint256[]) public sellerTrades;
    mapping(address => uint256[]) public buyerTrades;
    
    // KYC caching
    mapping(address => CachedKYC) private _cachedKYC;
    uint256 public kycCacheValidityDuration;
    
    // KYC settings
    uint8 public defaultMinKYCLevel;
    mapping(uint16 => bool) private _restrictedCountries;
    bool public kycEnforced;
    
    // For dispute resolution
    mapping(address => bool) public arbitrators;
    
    uint256 public totalVolume;
    uint256 public totalFees;

    // ============ v2 storage (appended) ============
    // Escrow accounting, so emergencyWithdraw can only take what no trade is owed.
    uint256 public escrowedTokens;          // security tokens deposited into open trades
    uint256 public escrowedStable;          // stablecoins deposited into open trades
    bool public escrowAccountingActive;     // set by initialize, or by initializeEscrowAccounting after an upgrade
    uint256 public escrowTrackedFrom;       // trades with id >= this are tracked as they happen
    uint256 public escrowLegacySynced;      // trades with id < this were added up by syncLegacyEscrow

    // ============ Events ============

    event TradeCreated(
        uint256 indexed tradeId,
        address indexed seller,
        uint256 tokenAmount,
        uint256 pricePerToken,
        uint256 totalStable,
        uint8 minKYCLevel
    );
    
    event BuyerAssigned(
        uint256 indexed tradeId,
        address indexed buyer
    );
    
    event SellerDeposited(
        uint256 indexed tradeId,
        address indexed seller,
        uint256 tokenAmount
    );
    
    event BuyerDeposited(
        uint256 indexed tradeId,
        address indexed buyer,
        uint256 stableAmount
    );
    
    event TradeCompleted(
        uint256 indexed tradeId,
        address indexed seller,
        address indexed buyer,
        uint256 tokenAmount,
        uint256 stableAmount,
        uint256 platformFee
    );
    
    event TradeCancelled(
        uint256 indexed tradeId,
        address indexed cancelledBy
    );
    
    event TradeExpired(
        uint256 indexed tradeId
    );
    
    event DisputeRaised(
        uint256 indexed tradeId,
        address indexed raisedBy,
        string reason
    );
    
    event DisputeResolved(
        uint256 indexed tradeId,
        address indexed resolver,
        bool sellerWins
    );
    
    event ArbitratorUpdated(address indexed arbitrator, bool approved);
    event FeeUpdated(uint256 oldFee, uint256 newFee);
    event KYCVerifierUpdated(address indexed oldVerifier, address indexed newVerifier);
    event KYCCached(address indexed wallet, uint8 level, uint16 countryCode, uint256 expiry);
    event MinKYCLevelUpdated(uint8 oldLevel, uint8 newLevel);
    event CountryRestrictionUpdated(uint16 indexed countryCode, bool restricted);
    event KYCEnforcementUpdated(bool enforced);
    event KYCCacheValidityUpdated(uint256 oldDuration, uint256 newDuration);

    // ============ Errors ============

    error InvalidAddress();
    error InvalidAmount();
    error TradeNotFound();
    error InvalidTradeStatus();
    error NotSeller();
    error NotBuyer();
    error NotParticipant();
    error AlreadyDeposited();
    error TradeIsExpired();
    error NotArbitrator();
    error InsufficientBalance();
    error TransferFailed();
    error InvalidKYCProof();
    error KYCExpired();
    error KYCLevelTooLow();
    error CountryRestricted();
    error KYCNotVerified();
    error InvalidKYCLevel();
    error EscrowAccountingIncomplete();
    error EscrowAccountingAlreadyActive();

    // ============ Modifiers ============

    modifier onlySeller(uint256 _tradeId) {
        if (trades[_tradeId].seller != msg.sender) revert NotSeller();
        _;
    }

    modifier onlyBuyer(uint256 _tradeId) {
        if (trades[_tradeId].buyer != msg.sender) revert NotBuyer();
        _;
    }

    modifier onlyParticipant(uint256 _tradeId) {
        Trade storage trade = trades[_tradeId];
        if (trade.seller != msg.sender && trade.buyer != msg.sender) {
            revert NotParticipant();
        }
        _;
    }

    modifier onlyArbitrator() {
        if (!arbitrators[msg.sender] && msg.sender != owner()) {
            revert NotArbitrator();
        }
        _;
    }

    modifier tradeExists(uint256 _tradeId) {
        if (trades[_tradeId].seller == address(0)) revert TradeNotFound();
        _;
    }

    modifier notExpired(uint256 _tradeId) {
        if (block.timestamp > trades[_tradeId].expiresAt) revert TradeIsExpired();
        _;
    }

    // ============ Initialization ============

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initialize the escrow contract
     * @param _owner Contract owner
     * @param _securityToken Security token address
     * @param _stablecoin Stablecoin address for payments
     * @param _kycVerifier KYC verifier contract address
     * @param _feeRecipient Platform fee recipient
     * @param _feeBps Platform fee in basis points
     */
    function initialize(
        address _owner,
        address _securityToken,
        address _stablecoin,
        address _kycVerifier,
        address _feeRecipient,
        uint256 _feeBps
    ) external initializer {
        if (_securityToken == address(0) || _stablecoin == address(0) || 
            _kycVerifier == address(0) || _feeRecipient == address(0)) {
            revert InvalidAddress();
        }

        __Ownable_init();
        __UUPSUpgradeable_init();
        __Pausable_init();
        __ReentrancyGuard_init();

        _transferOwnership(_owner);

        securityToken = IERC20(_securityToken);
        stablecoin = IERC20(_stablecoin);
        kycVerifier = IKYCVerifier(_kycVerifier);
        platformFeeRecipient = _feeRecipient;
        platformFeeBps = _feeBps;
        defaultExpirationTime = 24 hours;
        defaultMinKYCLevel = 1; // Basic KYC required by default
        kycCacheValidityDuration = 1 hours;
        kycEnforced = true;
        escrowAccountingActive = true;
        
        // Add default restricted countries (OFAC)
        _restrictedCountries[408] = true; // North Korea
        _restrictedCountries[364] = true; // Iran
        _restrictedCountries[760] = true; // Syria
        _restrictedCountries[192] = true; // Cuba
        
        emit KYCVerifierUpdated(address(0), _kycVerifier);
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    // ============ KYC Functions ============
    
    /**
     * @notice Cache KYC proof for a wallet
     * @param _wallet Wallet address
     * @param _proof KYC proof from backend
     */
    function cacheKYC(
        address _wallet,
        KYCProof calldata _proof
    ) external whenNotPaused {
        _verifyCacheKYC(_wallet, _proof);
        
        _cachedKYC[_wallet] = CachedKYC({
            level: _proof.level,
            countryCode: _proof.countryCode,
            expiry: _proof.expiry,
            cachedAt: block.timestamp
        });
        
        emit KYCCached(_wallet, _proof.level, _proof.countryCode, _proof.expiry);
    }
    
    /**
     * @notice Internal KYC verification for caching
     */
    function _verifyCacheKYC(
        address _wallet,
        KYCProof calldata _proof
    ) internal view {
        bool isValid = kycVerifier.verify(
            _wallet,
            _proof.level,
            _proof.countryCode,
            _proof.expiry,
            _proof.signature
        );
        
        if (!isValid) revert InvalidKYCProof();
        if (_proof.expiry < block.timestamp) revert KYCExpired();
    }
    
    /**
     * @notice Check if a wallet has valid cached KYC
     * @param _wallet Wallet to check
     * @param _minLevel Minimum required level
     * @return bool True if KYC is valid
     */
    function _hasValidKYC(address _wallet, uint8 _minLevel) internal view returns (bool) {
        if (!kycEnforced) return true;
        
        CachedKYC storage cached = _cachedKYC[_wallet];
        
        if (cached.cachedAt == 0) return false;
        if (block.timestamp > cached.cachedAt + kycCacheValidityDuration) return false;
        if (block.timestamp > cached.expiry) return false;
        if (cached.level < _minLevel) return false;
        if (_restrictedCountries[cached.countryCode]) return false;
        
        return true;
    }
    
    /**
     * @notice Verify KYC inline with proof
     */
    function _verifyKYCWithProof(
        address _wallet,
        KYCProof calldata _proof,
        uint8 _minLevel
    ) internal view {
        if (!kycEnforced) return;
        
        bool isValid = kycVerifier.verify(
            _wallet,
            _proof.level,
            _proof.countryCode,
            _proof.expiry,
            _proof.signature
        );
        
        if (!isValid) revert InvalidKYCProof();
        if (_proof.expiry < block.timestamp) revert KYCExpired();
        if (_proof.level < _minLevel) revert KYCLevelTooLow();
        if (_restrictedCountries[_proof.countryCode]) revert CountryRestricted();
    }
    
    /**
     * @notice Cache KYC from proof (internal helper)
     */
    function _cacheKYCFromProof(address _wallet, KYCProof calldata _proof) internal {
        _cachedKYC[_wallet] = CachedKYC({
            level: _proof.level,
            countryCode: _proof.countryCode,
            expiry: _proof.expiry,
            cachedAt: block.timestamp
        });
        
        emit KYCCached(_wallet, _proof.level, _proof.countryCode, _proof.expiry);
    }

    // ============ Trade Creation ============

    /**
     * @notice Create a new trade offer with KYC proof
     * @param _tokenAmount Amount of security tokens to sell
     * @param _pricePerToken Price per token in stablecoin (6 decimals for USDC)
     * @param _expirationTime Custom expiration (0 for default)
     * @param _minKYCLevel Minimum KYC level for buyer (0 for default)
     * @param _proof Seller's KYC proof
     * @return tradeId The created trade ID
     */
    function createTradeWithKYC(
        uint256 _tokenAmount,
        uint256 _pricePerToken,
        uint256 _expirationTime,
        uint8 _minKYCLevel,
        KYCProof calldata _proof
    ) external whenNotPaused returns (uint256 tradeId) {
        if (_tokenAmount == 0 || _pricePerToken == 0) revert InvalidAmount();
        
        _verifyKYCWithProof(msg.sender, _proof, defaultMinKYCLevel);
        _cacheKYCFromProof(msg.sender, _proof);

        tradeId = tradeCounter++;
        
        uint256 stableAmount = (_tokenAmount * _pricePerToken) / 1e18;
        uint256 expiration = _expirationTime > 0 ? _expirationTime : block.timestamp + defaultExpirationTime;
        uint8 buyerMinLevel = _minKYCLevel > 0 ? _minKYCLevel : defaultMinKYCLevel;

        trades[tradeId] = Trade({
            tradeId: tradeId,
            seller: msg.sender,
            buyer: address(0),
            tokenAmount: _tokenAmount,
            stableAmount: stableAmount,
            pricePerToken: _pricePerToken,
            createdAt: block.timestamp,
            expiresAt: expiration,
            status: TradeStatus.CREATED,
            sellerDeposited: false,
            buyerDeposited: false,
            minKYCLevel: buyerMinLevel,
            sellerCountryCode: _proof.countryCode
        });

        sellerTrades[msg.sender].push(tradeId);

        emit TradeCreated(tradeId, msg.sender, _tokenAmount, _pricePerToken, stableAmount, buyerMinLevel);
    }

    /**
     * @notice Create a new trade offer using cached KYC
     * @param _tokenAmount Amount of security tokens to sell
     * @param _pricePerToken Price per token in stablecoin
     * @param _expirationTime Custom expiration (0 for default)
     * @param _minKYCLevel Minimum KYC level for buyer (0 for default)
     * @return tradeId The created trade ID
     */
    function createTrade(
        uint256 _tokenAmount,
        uint256 _pricePerToken,
        uint256 _expirationTime,
        uint8 _minKYCLevel
    ) external whenNotPaused returns (uint256 tradeId) {
        if (_tokenAmount == 0 || _pricePerToken == 0) revert InvalidAmount();
        if (!_hasValidKYC(msg.sender, defaultMinKYCLevel)) revert KYCNotVerified();

        tradeId = tradeCounter++;
        
        uint256 stableAmount = (_tokenAmount * _pricePerToken) / 1e18;
        uint256 expiration = _expirationTime > 0 ? _expirationTime : block.timestamp + defaultExpirationTime;
        uint8 buyerMinLevel = _minKYCLevel > 0 ? _minKYCLevel : defaultMinKYCLevel;

        CachedKYC storage sellerKYC = _cachedKYC[msg.sender];

        trades[tradeId] = Trade({
            tradeId: tradeId,
            seller: msg.sender,
            buyer: address(0),
            tokenAmount: _tokenAmount,
            stableAmount: stableAmount,
            pricePerToken: _pricePerToken,
            createdAt: block.timestamp,
            expiresAt: expiration,
            status: TradeStatus.CREATED,
            sellerDeposited: false,
            buyerDeposited: false,
            minKYCLevel: buyerMinLevel,
            sellerCountryCode: sellerKYC.countryCode
        });

        sellerTrades[msg.sender].push(tradeId);

        emit TradeCreated(tradeId, msg.sender, _tokenAmount, _pricePerToken, stableAmount, buyerMinLevel);
    }

    /**
     * @notice Create trade with immediate deposit and KYC proof
     * @param _tokenAmount Amount of security tokens to sell
     * @param _pricePerToken Price per token in stablecoin
     * @param _expirationTime Custom expiration (0 for default)
     * @param _minKYCLevel Minimum KYC level for buyer
     * @param _proof Seller's KYC proof
     * @return tradeId The created trade ID
     */
    function createTradeAndDepositWithKYC(
        uint256 _tokenAmount,
        uint256 _pricePerToken,
        uint256 _expirationTime,
        uint8 _minKYCLevel,
        KYCProof calldata _proof
    ) external whenNotPaused nonReentrant returns (uint256 tradeId) {
        if (_tokenAmount == 0 || _pricePerToken == 0) revert InvalidAmount();
        if (securityToken.balanceOf(msg.sender) < _tokenAmount) revert InsufficientBalance();
        
        _verifyKYCWithProof(msg.sender, _proof, defaultMinKYCLevel);
        _cacheKYCFromProof(msg.sender, _proof);

        tradeId = tradeCounter++;
        
        uint256 stableAmount = (_tokenAmount * _pricePerToken) / 1e18;
        uint256 expiration = _expirationTime > 0 ? _expirationTime : block.timestamp + defaultExpirationTime;
        uint8 buyerMinLevel = _minKYCLevel > 0 ? _minKYCLevel : defaultMinKYCLevel;

        trades[tradeId] = Trade({
            tradeId: tradeId,
            seller: msg.sender,
            buyer: address(0),
            tokenAmount: _tokenAmount,
            stableAmount: stableAmount,
            pricePerToken: _pricePerToken,
            createdAt: block.timestamp,
            expiresAt: expiration,
            status: TradeStatus.SELLER_DEPOSITED,
            sellerDeposited: true,
            buyerDeposited: false,
            minKYCLevel: buyerMinLevel,
            sellerCountryCode: _proof.countryCode
        });

        sellerTrades[msg.sender].push(tradeId);

        _depositTokens(tradeId, _tokenAmount);

        emit TradeCreated(tradeId, msg.sender, _tokenAmount, _pricePerToken, stableAmount, buyerMinLevel);
        emit SellerDeposited(tradeId, msg.sender, _tokenAmount);
    }

    /**
     * @notice Create trade with immediate deposit using cached KYC
     */
    function createTradeAndDeposit(
        uint256 _tokenAmount,
        uint256 _pricePerToken,
        uint256 _expirationTime,
        uint8 _minKYCLevel
    ) external whenNotPaused nonReentrant returns (uint256 tradeId) {
        if (_tokenAmount == 0 || _pricePerToken == 0) revert InvalidAmount();
        if (securityToken.balanceOf(msg.sender) < _tokenAmount) revert InsufficientBalance();
        if (!_hasValidKYC(msg.sender, defaultMinKYCLevel)) revert KYCNotVerified();

        tradeId = tradeCounter++;
        
        uint256 stableAmount = (_tokenAmount * _pricePerToken) / 1e18;
        uint256 expiration = _expirationTime > 0 ? _expirationTime : block.timestamp + defaultExpirationTime;
        uint8 buyerMinLevel = _minKYCLevel > 0 ? _minKYCLevel : defaultMinKYCLevel;
        
        CachedKYC storage sellerKYC = _cachedKYC[msg.sender];

        trades[tradeId] = Trade({
            tradeId: tradeId,
            seller: msg.sender,
            buyer: address(0),
            tokenAmount: _tokenAmount,
            stableAmount: stableAmount,
            pricePerToken: _pricePerToken,
            createdAt: block.timestamp,
            expiresAt: expiration,
            status: TradeStatus.SELLER_DEPOSITED,
            sellerDeposited: true,
            buyerDeposited: false,
            minKYCLevel: buyerMinLevel,
            sellerCountryCode: sellerKYC.countryCode
        });

        sellerTrades[msg.sender].push(tradeId);

        _depositTokens(tradeId, _tokenAmount);

        emit TradeCreated(tradeId, msg.sender, _tokenAmount, _pricePerToken, stableAmount, buyerMinLevel);
        emit SellerDeposited(tradeId, msg.sender, _tokenAmount);
    }

    // ============ Trade Participation ============

    /**
     * @notice Buyer accepts a trade with KYC proof
     * @param _tradeId Trade ID to accept
     * @param _proof Buyer's KYC proof
     */
    function acceptTradeWithKYC(
        uint256 _tradeId,
        KYCProof calldata _proof
    ) external tradeExists(_tradeId) notExpired(_tradeId) whenNotPaused {
        Trade storage trade = trades[_tradeId];
        
        if (trade.status != TradeStatus.CREATED && trade.status != TradeStatus.SELLER_DEPOSITED) {
            revert InvalidTradeStatus();
        }
        if (trade.buyer != address(0)) revert InvalidTradeStatus();
        if (trade.seller == msg.sender) revert NotBuyer();
        
        _verifyKYCWithProof(msg.sender, _proof, trade.minKYCLevel);
        _cacheKYCFromProof(msg.sender, _proof);

        trade.buyer = msg.sender;
        buyerTrades[msg.sender].push(_tradeId);

        emit BuyerAssigned(_tradeId, msg.sender);
    }

    /**
     * @notice Buyer accepts a trade using cached KYC
     * @param _tradeId Trade ID to accept
     */
    function acceptTrade(uint256 _tradeId) 
        external 
        tradeExists(_tradeId) 
        notExpired(_tradeId) 
        whenNotPaused 
    {
        Trade storage trade = trades[_tradeId];
        
        if (trade.status != TradeStatus.CREATED && trade.status != TradeStatus.SELLER_DEPOSITED) {
            revert InvalidTradeStatus();
        }
        if (trade.buyer != address(0)) revert InvalidTradeStatus();
        if (trade.seller == msg.sender) revert NotBuyer();
        if (!_hasValidKYC(msg.sender, trade.minKYCLevel)) revert KYCNotVerified();

        trade.buyer = msg.sender;
        buyerTrades[msg.sender].push(_tradeId);

        emit BuyerAssigned(_tradeId, msg.sender);
    }

    /**
     * @notice Seller deposits tokens
     * @param _tradeId Trade ID
     */
    function sellerDeposit(uint256 _tradeId) 
        external 
        nonReentrant 
        tradeExists(_tradeId) 
        notExpired(_tradeId)
        onlySeller(_tradeId)
        whenNotPaused 
    {
        Trade storage trade = trades[_tradeId];
        
        if (trade.sellerDeposited) revert AlreadyDeposited();
        if (securityToken.balanceOf(msg.sender) < trade.tokenAmount) revert InsufficientBalance();
        // Seller KYC was verified at trade creation

        trade.sellerDeposited = true;
        
        if (trade.status == TradeStatus.CREATED) {
            trade.status = TradeStatus.SELLER_DEPOSITED;
        }

        _depositTokens(_tradeId, trade.tokenAmount);

        emit SellerDeposited(_tradeId, msg.sender, trade.tokenAmount);

        _tryCompleteTrade(_tradeId);
    }

    /**
     * @notice Buyer deposits stablecoin
     * @param _tradeId Trade ID
     */
    function buyerDeposit(uint256 _tradeId) 
        external 
        nonReentrant 
        tradeExists(_tradeId) 
        notExpired(_tradeId)
        onlyBuyer(_tradeId)
        whenNotPaused 
    {
        Trade storage trade = trades[_tradeId];
        
        if (trade.buyerDeposited) revert AlreadyDeposited();
        if (stablecoin.balanceOf(msg.sender) < trade.stableAmount) revert InsufficientBalance();
        // Buyer KYC was verified at trade acceptance

        trade.buyerDeposited = true;
        trade.status = TradeStatus.BUYER_DEPOSITED;

        _depositStable(_tradeId, trade.stableAmount);

        emit BuyerDeposited(_tradeId, msg.sender, trade.stableAmount);

        _tryCompleteTrade(_tradeId);
    }

    /**
     * @notice Accept trade and deposit in one transaction with KYC proof
     * @param _tradeId Trade ID
     * @param _proof Buyer's KYC proof
     */
    function acceptAndDepositWithKYC(
        uint256 _tradeId,
        KYCProof calldata _proof
    ) external nonReentrant tradeExists(_tradeId) notExpired(_tradeId) whenNotPaused {
        Trade storage trade = trades[_tradeId];
        
        if (trade.status != TradeStatus.CREATED && trade.status != TradeStatus.SELLER_DEPOSITED) {
            revert InvalidTradeStatus();
        }
        if (trade.buyer != address(0)) revert InvalidTradeStatus();
        if (trade.seller == msg.sender) revert NotBuyer();
        if (stablecoin.balanceOf(msg.sender) < trade.stableAmount) revert InsufficientBalance();
        
        _verifyKYCWithProof(msg.sender, _proof, trade.minKYCLevel);
        _cacheKYCFromProof(msg.sender, _proof);

        trade.buyer = msg.sender;
        trade.buyerDeposited = true;
        trade.status = TradeStatus.BUYER_DEPOSITED;
        
        buyerTrades[msg.sender].push(_tradeId);

        _depositStable(_tradeId, trade.stableAmount);

        emit BuyerAssigned(_tradeId, msg.sender);
        emit BuyerDeposited(_tradeId, msg.sender, trade.stableAmount);

        _tryCompleteTrade(_tradeId);
    }

    /**
     * @notice Accept trade and deposit in one transaction using cached KYC
     * @param _tradeId Trade ID
     */
    function acceptAndDeposit(uint256 _tradeId) 
        external 
        nonReentrant 
        tradeExists(_tradeId) 
        notExpired(_tradeId)
        whenNotPaused 
    {
        Trade storage trade = trades[_tradeId];
        
        if (trade.status != TradeStatus.CREATED && trade.status != TradeStatus.SELLER_DEPOSITED) {
            revert InvalidTradeStatus();
        }
        if (trade.buyer != address(0)) revert InvalidTradeStatus();
        if (trade.seller == msg.sender) revert NotBuyer();
        if (stablecoin.balanceOf(msg.sender) < trade.stableAmount) revert InsufficientBalance();
        if (!_hasValidKYC(msg.sender, trade.minKYCLevel)) revert KYCNotVerified();

        trade.buyer = msg.sender;
        trade.buyerDeposited = true;
        trade.status = TradeStatus.BUYER_DEPOSITED;
        
        buyerTrades[msg.sender].push(_tradeId);

        _depositStable(_tradeId, trade.stableAmount);

        emit BuyerAssigned(_tradeId, msg.sender);
        emit BuyerDeposited(_tradeId, msg.sender, trade.stableAmount);

        _tryCompleteTrade(_tradeId);
    }

    // ============ Trade Completion ============

    /**
     * @notice Internal function to complete trade if both parties deposited
     */
    function _tryCompleteTrade(uint256 _tradeId) internal {
        Trade storage trade = trades[_tradeId];

        if (!trade.sellerDeposited || !trade.buyerDeposited) return;
        if (trade.status == TradeStatus.COMPLETED) return;

        // Calculate platform fee
        uint256 platformFee = (trade.stableAmount * platformFeeBps) / 10000;
        uint256 sellerReceives = trade.stableAmount - platformFee;

        // Update status
        trade.status = TradeStatus.COMPLETED;

        // Transfer tokens to buyer
        _payTokens(_tradeId, trade.buyer, trade.tokenAmount);

        // Transfer stablecoin to seller (minus fee)
        _payStable(_tradeId, trade.seller, sellerReceives);

        // Transfer fee to platform
        if (platformFee > 0) {
            _payStable(_tradeId, platformFeeRecipient, platformFee);
        }

        // Update stats
        totalVolume += trade.stableAmount;
        totalFees += platformFee;

        emit TradeCompleted(
            _tradeId,
            trade.seller,
            trade.buyer,
            trade.tokenAmount,
            trade.stableAmount,
            platformFee
        );
    }

    // ============ Trade Cancellation ============

    /**
     * @notice Cancel a trade (only if not completed)
     * @param _tradeId Trade ID
     */
    function cancelTrade(uint256 _tradeId) 
        external 
        nonReentrant 
        tradeExists(_tradeId) 
        onlyParticipant(_tradeId)
    {
        Trade storage trade = trades[_tradeId];
        
        // A disputed trade is settled by an arbitrator through resolveDispute only
        if (trade.status == TradeStatus.COMPLETED || 
            trade.status == TradeStatus.CANCELLED || 
            trade.status == TradeStatus.EXPIRED ||
            trade.status == TradeStatus.DISPUTED) {
            revert InvalidTradeStatus();
        }

        // Refund deposited amounts
        if (trade.sellerDeposited) {
            _payTokens(_tradeId, trade.seller, trade.tokenAmount);
        }
        
        if (trade.buyerDeposited) {
            _payStable(_tradeId, trade.buyer, trade.stableAmount);
        }

        trade.status = TradeStatus.CANCELLED;

        emit TradeCancelled(_tradeId, msg.sender);
    }

    /**
     * @notice Expire and refund a trade that passed deadline
     * @param _tradeId Trade ID
     */
    function expireTrade(uint256 _tradeId) external nonReentrant tradeExists(_tradeId) {
        Trade storage trade = trades[_tradeId];
        
        if (block.timestamp <= trade.expiresAt) revert InvalidTradeStatus();
        if (trade.status == TradeStatus.COMPLETED || 
            trade.status == TradeStatus.CANCELLED || 
            trade.status == TradeStatus.EXPIRED ||
            trade.status == TradeStatus.DISPUTED) {
            revert InvalidTradeStatus();
        }

        // Refund deposited amounts
        if (trade.sellerDeposited) {
            _payTokens(_tradeId, trade.seller, trade.tokenAmount);
        }
        
        if (trade.buyerDeposited) {
            _payStable(_tradeId, trade.buyer, trade.stableAmount);
        }

        trade.status = TradeStatus.EXPIRED;

        emit TradeExpired(_tradeId);
    }

    // ============ Dispute Resolution ============

    /**
     * @notice Raise a dispute on a trade
     * @param _tradeId Trade ID
     * @param _reason Reason for dispute
     */
    function raiseDispute(uint256 _tradeId, string calldata _reason) 
        external 
        tradeExists(_tradeId) 
        onlyParticipant(_tradeId) 
    {
        Trade storage trade = trades[_tradeId];
        
        if (trade.status == TradeStatus.COMPLETED || 
            trade.status == TradeStatus.CANCELLED || 
            trade.status == TradeStatus.EXPIRED) {
            revert InvalidTradeStatus();
        }

        trade.status = TradeStatus.DISPUTED;

        emit DisputeRaised(_tradeId, msg.sender, _reason);
    }

    /**
     * @notice Resolve a dispute (arbitrator only)
     * @param _tradeId Trade ID
     * @param _sellerWins If true, seller gets tokens back; if false, buyer wins
     */
    function resolveDispute(uint256 _tradeId, bool _sellerWins) 
        external 
        nonReentrant 
        tradeExists(_tradeId) 
        onlyArbitrator 
    {
        Trade storage trade = trades[_tradeId];
        
        if (trade.status != TradeStatus.DISPUTED) revert InvalidTradeStatus();

        if (_sellerWins) {
            // Return tokens to seller, stables to buyer
            if (trade.sellerDeposited) {
                _payTokens(_tradeId, trade.seller, trade.tokenAmount);
            }
            if (trade.buyerDeposited) {
                _payStable(_tradeId, trade.buyer, trade.stableAmount);
            }
        } else {
            // Complete trade in buyer's favor
            if (trade.sellerDeposited && trade.buyer != address(0)) {
                _payTokens(_tradeId, trade.buyer, trade.tokenAmount);
            }
            if (trade.buyerDeposited) {
                uint256 platformFee = (trade.stableAmount * platformFeeBps) / 10000;
                uint256 sellerReceives = trade.stableAmount - platformFee;
                _payStable(_tradeId, trade.seller, sellerReceives);
                if (platformFee > 0) {
                    _payStable(_tradeId, platformFeeRecipient, platformFee);
                }
            }
        }

        trade.status = TradeStatus.CANCELLED;

        emit DisputeResolved(_tradeId, msg.sender, _sellerWins);
    }

    // ============ Admin Functions ============

    function setArbitrator(address _arbitrator, bool _approved) external onlyOwner {
        if (_arbitrator == address(0)) revert InvalidAddress();
        arbitrators[_arbitrator] = _approved;
        emit ArbitratorUpdated(_arbitrator, _approved);
    }

    function setPlatformFee(uint256 _feeBps) external onlyOwner {
        if (_feeBps > 1000) revert InvalidAmount(); // Max 10%
        uint256 oldFee = platformFeeBps;
        platformFeeBps = _feeBps;
        emit FeeUpdated(oldFee, _feeBps);
    }

    function setPlatformFeeRecipient(address _recipient) external onlyOwner {
        if (_recipient == address(0)) revert InvalidAddress();
        platformFeeRecipient = _recipient;
    }

    function setDefaultExpiration(uint256 _duration) external onlyOwner {
        defaultExpirationTime = _duration;
    }
    
    function setKYCVerifier(address _kycVerifier) external onlyOwner {
        if (_kycVerifier == address(0)) revert InvalidAddress();
        address oldVerifier = address(kycVerifier);
        kycVerifier = IKYCVerifier(_kycVerifier);
        emit KYCVerifierUpdated(oldVerifier, _kycVerifier);
    }
    
    function setDefaultMinKYCLevel(uint8 _level) external onlyOwner {
        if (_level > 4) revert InvalidKYCLevel();
        uint8 oldLevel = defaultMinKYCLevel;
        defaultMinKYCLevel = _level;
        emit MinKYCLevelUpdated(oldLevel, _level);
    }
    
    function setCountryRestriction(uint16 _countryCode, bool _restricted) external onlyOwner {
        _restrictedCountries[_countryCode] = _restricted;
        emit CountryRestrictionUpdated(_countryCode, _restricted);
    }
    
    function batchSetCountryRestrictions(
        uint16[] calldata _countryCodes,
        bool _restricted
    ) external onlyOwner {
        for (uint256 i = 0; i < _countryCodes.length; i++) {
            _restrictedCountries[_countryCodes[i]] = _restricted;
            emit CountryRestrictionUpdated(_countryCodes[i], _restricted);
        }
    }
    
    function setKYCEnforced(bool _enforced) external onlyOwner {
        kycEnforced = _enforced;
        emit KYCEnforcementUpdated(_enforced);
    }
    
    function setKYCCacheValidityDuration(uint256 _duration) external onlyOwner {
        uint256 oldDuration = kycCacheValidityDuration;
        kycCacheValidityDuration = _duration;
        emit KYCCacheValidityUpdated(oldDuration, _duration);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Withdraw tokens the escrow holds beyond what open trades are owed
     *         (stray transfers, fees left behind). Deposits of open trades cannot be taken.
     */
    function emergencyWithdraw(address _token, uint256 _amount) external onlyOwner {
        if (_token == address(securityToken) || _token == address(stablecoin)) {
            if (!escrowAccountingActive || escrowLegacySynced < escrowTrackedFrom) revert EscrowAccountingIncomplete();
            uint256 owed = _token == address(securityToken) ? escrowedTokens : escrowedStable;
            if (IERC20(_token).balanceOf(address(this)) < owed + _amount) revert InsufficientBalance();
        }
        IERC20(_token).safeTransfer(owner(), _amount);
    }

    /// @notice Amount of `_token` that emergencyWithdraw could take right now
    function withdrawableBalance(address _token) external view returns (uint256) {
        uint256 balance = IERC20(_token).balanceOf(address(this));
        if (_token != address(securityToken) && _token != address(stablecoin)) return balance;
        if (!escrowAccountingActive || escrowLegacySynced < escrowTrackedFrom) return 0;
        uint256 owed = _token == address(securityToken) ? escrowedTokens : escrowedStable;
        return balance > owed ? balance - owed : 0;
    }

    /**
     * @notice Turn on escrow accounting on a proxy upgraded from v1. Trades created from now on are
     *         tracked live; existing ones are added up by syncLegacyEscrow, and emergencyWithdraw
     *         stays disabled for the escrowed tokens until that has covered all of them.
     */
    function initializeEscrowAccounting() external onlyOwner {
        if (escrowAccountingActive) revert EscrowAccountingAlreadyActive();
        escrowAccountingActive = true;
        escrowTrackedFrom = tradeCounter;
        escrowLegacySynced = 0;
    }

    /// @notice Add up the open deposits of up to `_maxTrades` pre-upgrade trades. Anyone may call.
    function syncLegacyEscrow(uint256 _maxTrades) external {
        if (!escrowAccountingActive) revert EscrowAccountingIncomplete();
        uint256 id = escrowLegacySynced;
        uint256 end = escrowTrackedFrom;
        for (uint256 n = 0; id < end && n < _maxTrades; n++) {
            Trade storage trade = trades[id];
            if (trade.status != TradeStatus.COMPLETED &&
                trade.status != TradeStatus.CANCELLED &&
                trade.status != TradeStatus.EXPIRED) {
                if (trade.sellerDeposited) escrowedTokens += trade.tokenAmount;
                if (trade.buyerDeposited) escrowedStable += trade.stableAmount;
            }
            id++;
        }
        escrowLegacySynced = id;
    }

    // ============ Escrow Accounting ============

    function _escrowTracked(uint256 _tradeId) internal view returns (bool) {
        return escrowAccountingActive && (_tradeId >= escrowTrackedFrom || _tradeId < escrowLegacySynced);
    }

    function _depositTokens(uint256 _tradeId, uint256 _amount) internal {
        securityToken.safeTransferFrom(msg.sender, address(this), _amount);
        if (_escrowTracked(_tradeId)) escrowedTokens += _amount;
    }

    function _depositStable(uint256 _tradeId, uint256 _amount) internal {
        stablecoin.safeTransferFrom(msg.sender, address(this), _amount);
        if (_escrowTracked(_tradeId)) escrowedStable += _amount;
    }

    function _payTokens(uint256 _tradeId, address _to, uint256 _amount) internal {
        if (_escrowTracked(_tradeId)) escrowedTokens = escrowedTokens > _amount ? escrowedTokens - _amount : 0;
        securityToken.safeTransfer(_to, _amount);
    }

    function _payStable(uint256 _tradeId, address _to, uint256 _amount) internal {
        if (_escrowTracked(_tradeId)) escrowedStable = escrowedStable > _amount ? escrowedStable - _amount : 0;
        stablecoin.safeTransfer(_to, _amount);
    }

    // ============ View Functions ============

    function getTrade(uint256 _tradeId) external view returns (Trade memory) {
        return trades[_tradeId];
    }

    function getSellerTrades(address _seller) external view returns (uint256[] memory) {
        return sellerTrades[_seller];
    }

    function getBuyerTrades(address _buyer) external view returns (uint256[] memory) {
        return buyerTrades[_buyer];
    }

    function getActiveTradesCount() external view returns (uint256 count) {
        for (uint256 i = 0; i < tradeCounter; i++) {
            if (trades[i].status == TradeStatus.CREATED || 
                trades[i].status == TradeStatus.SELLER_DEPOSITED ||
                trades[i].status == TradeStatus.BUYER_DEPOSITED) {
                count++;
            }
        }
    }

    function getOpenTrades(uint256 _offset, uint256 _limit) external view returns (Trade[] memory) {
        uint256 count = 0;
        
        for (uint256 i = 0; i < tradeCounter; i++) {
            if (trades[i].status == TradeStatus.CREATED || 
                trades[i].status == TradeStatus.SELLER_DEPOSITED) {
                if (block.timestamp <= trades[i].expiresAt) {
                    count++;
                }
            }
        }

        if (_offset >= count) return new Trade[](0);

        uint256 resultSize = _limit;
        if (_offset + _limit > count) resultSize = count - _offset;

        Trade[] memory result = new Trade[](resultSize);
        uint256 found = 0;
        uint256 added = 0;

        for (uint256 i = 0; i < tradeCounter && added < resultSize; i++) {
            if (trades[i].status == TradeStatus.CREATED || 
                trades[i].status == TradeStatus.SELLER_DEPOSITED) {
                if (block.timestamp <= trades[i].expiresAt) {
                    if (found >= _offset) {
                        result[added] = trades[i];
                        added++;
                    }
                    found++;
                }
            }
        }

        return result;
    }

    function getStats() external view returns (
        uint256 _totalTrades,
        uint256 _totalVolume,
        uint256 _totalFees,
        uint256 _platformFeeBps
    ) {
        return (tradeCounter, totalVolume, totalFees, platformFeeBps);
    }
    
    /**
     * @notice Check if wallet has valid KYC for trading
     */
    function isKYCValid(address _wallet) external view returns (bool) {
        return _hasValidKYC(_wallet, defaultMinKYCLevel);
    }
    
    /**
     * @notice Check if wallet can participate in a specific trade
     */
    function canParticipateInTrade(
        address _wallet,
        uint256 _tradeId
    ) external view tradeExists(_tradeId) returns (bool) {
        Trade storage trade = trades[_tradeId];
        return _hasValidKYC(_wallet, trade.minKYCLevel);
    }
    
    /**
     * @notice Get cached KYC data for a wallet
     */
    function getCachedKYC(address _wallet) external view returns (
        uint8 level,
        uint16 countryCode,
        uint256 expiry,
        uint256 cachedAt,
        bool isValid
    ) {
        CachedKYC storage cached = _cachedKYC[_wallet];
        bool valid = _hasValidKYC(_wallet, 1);
        
        return (
            cached.level,
            cached.countryCode,
            cached.expiry,
            cached.cachedAt,
            valid
        );
    }
    
    /**
     * @notice Check if country is restricted
     */
    function isCountryRestricted(uint16 _countryCode) external view returns (bool) {
        return _restrictedCountries[_countryCode];
    }
    
    /**
     * @notice Get KYC verifier address
     */
    function getKYCVerifier() external view returns (address) {
        return address(kycVerifier);
    }
}

contracts/trade/TradeEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

/**
 * @title TradeEscrow
 * @notice Milestone-based escrow contract for international trade payments
 * @dev Supports multiple ERC20 tokens and milestone-based fund releases
 */
contract TradeEscrow is ReentrancyGuard, AccessControl, Pausable {
    using SafeERC20 for IERC20;

    // =============================================================================
    // ROLES
    // =============================================================================
    
    bytes32 public constant PLATFORM_ADMIN = keccak256("PLATFORM_ADMIN");
    bytes32 public constant ARBITER_ROLE = keccak256("ARBITER_ROLE");
    bytes32 public constant COMPLIANCE_ROLE = keccak256("COMPLIANCE_ROLE");

    // =============================================================================
    // ENUMS & STRUCTS
    // =============================================================================

    enum DealStatus {
        Created,
        Funded,
        InProgress,
        Completed,
        Disputed,
        Cancelled,
        Refunded
    }

    enum MilestoneStatus {
        Pending,
        InProgress,
        AwaitingApproval,
        Approved,
        Released,
        Disputed,
        Failed
    }

    struct Milestone {
        string name;
        string description;
        uint256 releasePercentage; // Basis points (10000 = 100%)
        uint256 releaseAmount;
        MilestoneStatus status;
        bytes32 documentHash; // Required document hash for verification
        uint256 completedAt;
        uint256 releasedAt;
    }

    struct Deal {
        string dealId;
        address buyer;
        address seller;
        address paymentToken;
        uint256 totalAmount;
        uint256 depositedAmount;
        uint256 releasedAmount;
        uint256 refundedAmount;
        DealStatus status;
        uint256 createdAt;
        uint256 fundedAt;
        uint256 completedAt;
        uint256 disputeDeadline;
        bool buyerKycVerified;
        bool sellerKycVerified;
    }

    struct Dispute {
        uint256 dealIndex;
        address initiator;
        string reason;
        uint256 claimedAmount;
        uint256 filedAt;
        uint256 resolvedAt;
        address resolver;
        bool resolved;
        string resolution;
    }

    // =============================================================================
    // STATE VARIABLES
    // =============================================================================

    Deal[] public deals;
    mapping(uint256 => Milestone[]) public dealMilestones;
    mapping(uint256 => Dispute) public disputes;
    
    mapping(string => uint256) public dealIdToIndex;
    mapping(address => uint256[]) public buyerDeals;
    mapping(address => uint256[]) public sellerDeals;
    
    address public platformFeeRecipient;
    uint256 public platformFeeBps = 50; // 0.5% default
    uint256 public disputeResolutionPeriod = 14 days;
    
    mapping(address => bool) public supportedTokens;

    // =============================================================================
    // EVENTS
    // =============================================================================

    event DealCreated(
        uint256 indexed dealIndex,
        string dealId,
        address indexed buyer,
        address indexed seller,
        address paymentToken,
        uint256 totalAmount
    );

    event DealFunded(
        uint256 indexed dealIndex,
        uint256 amount,
        uint256 platformFee
    );

    event MilestoneAdded(
        uint256 indexed dealIndex,
        uint256 milestoneIndex,
        string name,
        uint256 releasePercentage
    );

    event MilestoneCompleted(
        uint256 indexed dealIndex,
        uint256 milestoneIndex,
        bytes32 documentHash
    );

    event MilestoneApproved(
        uint256 indexed dealIndex,
        uint256 milestoneIndex,
        address approver
    );

    event FundsReleased(
        uint256 indexed dealIndex,
        uint256 milestoneIndex,
        uint256 amount,
        address recipient
    );

    event DisputeInitiated(
        uint256 indexed dealIndex,
        address indexed initiator,
        string reason
    );

    event DisputeResolved(
        uint256 indexed dealIndex,
        address resolver,
        string resolution
    );

    event DealCompleted(uint256 indexed dealIndex, uint256 completedAt);
    event DealCancelled(uint256 indexed dealIndex, string reason);
    event FundsRefunded(uint256 indexed dealIndex, uint256 amount, address recipient);
    event KycStatusUpdated(uint256 indexed dealIndex, address party, bool verified);

    // =============================================================================
    // MODIFIERS
    // =============================================================================

    modifier onlyDealParty(uint256 _dealIndex) {
        require(
            msg.sender == deals[_dealIndex].buyer || 
            msg.sender == deals[_dealIndex].seller,
            "Not a deal party"
        );
        _;
    }

    modifier onlyBuyer(uint256 _dealIndex) {
        require(msg.sender == deals[_dealIndex].buyer, "Not the buyer");
        _;
    }

    modifier onlySeller(uint256 _dealIndex) {
        require(msg.sender == deals[_dealIndex].seller, "Not the seller");
        _;
    }

    modifier dealExists(uint256 _dealIndex) {
        require(_dealIndex < deals.length, "Deal does not exist");
        _;
    }

    modifier inStatus(uint256 _dealIndex, DealStatus _status) {
        require(deals[_dealIndex].status == _status, "Invalid deal status");
        _;
    }

    modifier kycVerified(uint256 _dealIndex) {
        require(
            deals[_dealIndex].buyerKycVerified && 
            deals[_dealIndex].sellerKycVerified,
            "KYC not verified"
        );
        _;
    }

    // =============================================================================
    // CONSTRUCTOR
    // =============================================================================

    constructor(address _feeRecipient) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PLATFORM_ADMIN, msg.sender);
        platformFeeRecipient = _feeRecipient;
    }

    // =============================================================================
    // ADMIN FUNCTIONS
    // =============================================================================

    function setSupportedToken(address _token, bool _supported) 
        external 
        onlyRole(PLATFORM_ADMIN) 
    {
        supportedTokens[_token] = _supported;
    }

    function setPlatformFee(uint256 _feeBps) 
        external 
        onlyRole(PLATFORM_ADMIN) 
    {
        require(_feeBps <= 500, "Fee too high"); // Max 5%
        platformFeeBps = _feeBps;
    }

    function setFeeRecipient(address _recipient) 
        external 
        onlyRole(PLATFORM_ADMIN) 
    {
        require(_recipient != address(0), "Invalid address");
        platformFeeRecipient = _recipient;
    }

    function setDisputePeriod(uint256 _period) 
        external 
        onlyRole(PLATFORM_ADMIN) 
    {
        disputeResolutionPeriod = _period;
    }

    function updateKycStatus(
        uint256 _dealIndex,
        address _party,
        bool _verified
    ) 
        external 
        onlyRole(COMPLIANCE_ROLE)
        dealExists(_dealIndex) 
    {
        Deal storage deal = deals[_dealIndex];
        
        if (_party == deal.buyer) {
            deal.buyerKycVerified = _verified;
        } else if (_party == deal.seller) {
            deal.sellerKycVerified = _verified;
        } else {
            revert("Invalid party");
        }
        
        emit KycStatusUpdated(_dealIndex, _party, _verified);
    }

    function pause() external onlyRole(PLATFORM_ADMIN) {
        _pause();
    }

    function unpause() external onlyRole(PLATFORM_ADMIN) {
        _unpause();
    }

    // =============================================================================
    // DEAL MANAGEMENT
    // =============================================================================

    function createDeal(
        string calldata _dealId,
        address _seller,
        address _paymentToken,
        uint256 _totalAmount
    ) 
        external 
        whenNotPaused 
        returns (uint256) 
    {
        require(bytes(_dealId).length > 0, "Invalid deal ID");
        require(_seller != address(0) && _seller != msg.sender, "Invalid seller");
        require(supportedTokens[_paymentToken], "Token not supported");
        require(_totalAmount > 0, "Invalid amount");
        require(dealIdToIndex[_dealId] == 0 || deals.length == 0, "Deal ID exists");

        uint256 dealIndex = deals.length;
        
        deals.push(Deal({
            dealId: _dealId,
            buyer: msg.sender,
            seller: _seller,
            paymentToken: _paymentToken,
            totalAmount: _totalAmount,
            depositedAmount: 0,
            releasedAmount: 0,
            refundedAmount: 0,
            status: DealStatus.Created,
            createdAt: block.timestamp,
            fundedAt: 0,
            completedAt: 0,
            disputeDeadline: 0,
            buyerKycVerified: false,
            sellerKycVerified: false
        }));

        dealIdToIndex[_dealId] = dealIndex;
        buyerDeals[msg.sender].push(dealIndex);
        sellerDeals[_seller].push(dealIndex);

        emit DealCreated(
            dealIndex,
            _dealId,
            msg.sender,
            _seller,
            _paymentToken,
            _totalAmount
        );

        return dealIndex;
    }

    function addMilestone(
        uint256 _dealIndex,
        string calldata _name,
        string calldata _description,
        uint256 _releasePercentage
    ) 
        external 
        dealExists(_dealIndex)
        onlyDealParty(_dealIndex)
        inStatus(_dealIndex, DealStatus.Created)
    {
        require(_releasePercentage <= 10000, "Invalid percentage");
        
        uint256 totalPercentage = _releasePercentage;
        Milestone[] storage milestones = dealMilestones[_dealIndex];
        
        for (uint256 i = 0; i < milestones.length; i++) {
            totalPercentage += milestones[i].releasePercentage;
        }
        require(totalPercentage <= 10000, "Total exceeds 100%");

        Deal storage deal = deals[_dealIndex];
        uint256 releaseAmount = (deal.totalAmount * _releasePercentage) / 10000;

        milestones.push(Milestone({
            name: _name,
            description: _description,
            releasePercentage: _releasePercentage,
            releaseAmount: releaseAmount,
            status: MilestoneStatus.Pending,
            documentHash: bytes32(0),
            completedAt: 0,
            releasedAt: 0
        }));

        emit MilestoneAdded(
            _dealIndex,
            milestones.length - 1,
            _name,
            _releasePercentage
        );
    }

    function fundDeal(uint256 _dealIndex) 
        external 
        nonReentrant
        whenNotPaused
        dealExists(_dealIndex)
        onlyBuyer(_dealIndex)
        inStatus(_dealIndex, DealStatus.Created)
        kycVerified(_dealIndex)
    {
        Deal storage deal = deals[_dealIndex];
        Milestone[] storage milestones = dealMilestones[_dealIndex];
        
        require(milestones.length > 0, "No milestones defined");
        
        // Verify total milestone percentage equals 100%
        uint256 totalPercentage = 0;
        for (uint256 i = 0; i < milestones.length; i++) {
            totalPercentage += milestones[i].releasePercentage;
        }
        require(totalPercentage == 10000, "Milestones must total 100%");

        uint256 platformFee = (deal.totalAmount * platformFeeBps) / 10000;
        uint256 totalRequired = deal.totalAmount + platformFee;

        IERC20 token = IERC20(deal.paymentToken);
        token.safeTransferFrom(msg.sender, address(this), totalRequired);
        
        if (platformFee > 0) {
            token.safeTransfer(platformFeeRecipient, platformFee);
        }

        deal.depositedAmount = deal.totalAmount;
        deal.status = DealStatus.Funded;
        deal.fundedAt = block.timestamp;

        // Set first milestone to InProgress
        if (milestones.length > 0) {
            milestones[0].status = MilestoneStatus.InProgress;
        }

        emit DealFunded(_dealIndex, deal.totalAmount, platformFee);
    }

    // =============================================================================
    // MILESTONE MANAGEMENT
    // =============================================================================

    function completeMilestone(
        uint256 _dealIndex,
        uint256 _milestoneIndex,
        bytes32 _documentHash
    ) 
        external 
        dealExists(_dealIndex)
        onlySeller(_dealIndex)
    {
        Deal storage deal = deals[_dealIndex];
        require(
            deal.status == DealStatus.Funded || 
            deal.status == DealStatus.InProgress,
            "Invalid deal status"
        );

        Milestone[] storage milestones = dealMilestones[_dealIndex];
        require(_milestoneIndex < milestones.length, "Invalid milestone");
        
        Milestone storage milestone = milestones[_milestoneIndex];
        require(
            milestone.status == MilestoneStatus.InProgress,
            "Milestone not in progress"
        );

        milestone.documentHash = _documentHash;
        milestone.status = MilestoneStatus.AwaitingApproval;
        milestone.completedAt = block.timestamp;

        if (deal.status == DealStatus.Funded) {
            deal.status = DealStatus.InProgress;
        }

        emit MilestoneCompleted(_dealIndex, _milestoneIndex, _documentHash);
    }

    function approveMilestone(
        uint256 _dealIndex,
        uint256 _milestoneIndex
    ) 
        external 
        nonReentrant
        dealExists(_dealIndex)
        onlyBuyer(_dealIndex)
    {
        Deal storage deal = deals[_dealIndex];
        require(
            deal.status == DealStatus.InProgress,
            "Deal not in progress"
        );

        Milestone[] storage milestones = dealMilestones[_dealIndex];
        require(_milestoneIndex < milestones.length, "Invalid milestone");
        
        Milestone storage milestone = milestones[_milestoneIndex];
        require(
            milestone.status == MilestoneStatus.AwaitingApproval,
            "Milestone not awaiting approval"
        );

        milestone.status = MilestoneStatus.Approved;

        emit MilestoneApproved(_dealIndex, _milestoneIndex, msg.sender);

        // Release funds
        _releaseMilestoneFunds(_dealIndex, _milestoneIndex);
    }

    function _releaseMilestoneFunds(
        uint256 _dealIndex,
        uint256 _milestoneIndex
    ) internal {
        Deal storage deal = deals[_dealIndex];
        Milestone storage milestone = dealMilestones[_dealIndex][_milestoneIndex];
        
        require(milestone.status == MilestoneStatus.Approved, "Not approved");
        require(milestone.releaseAmount > 0, "No amount to release");
        require(
            deal.depositedAmount >= deal.releasedAmount + milestone.releaseAmount,
            "Insufficient funds"
        );

        milestone.status = MilestoneStatus.Released;
        milestone.releasedAt = block.timestamp;
        deal.releasedAmount += milestone.releaseAmount;

        IERC20(deal.paymentToken).safeTransfer(deal.seller, milestone.releaseAmount);

        emit FundsReleased(
            _dealIndex,
            _milestoneIndex,
            milestone.releaseAmount,
            deal.seller
        );

        // Check if all milestones are released
        _checkDealCompletion(_dealIndex);

        // Set next milestone to InProgress
        Milestone[] storage milestones = dealMilestones[_dealIndex];
        if (_milestoneIndex + 1 < milestones.length) {
            milestones[_milestoneIndex + 1].status = MilestoneStatus.InProgress;
        }
    }

    function _checkDealCompletion(uint256 _dealIndex) internal {
        Deal storage deal = deals[_dealIndex];
        Milestone[] storage milestones = dealMilestones[_dealIndex];
        
        bool allReleased = true;
        for (uint256 i = 0; i < milestones.length; i++) {
            if (milestones[i].status != MilestoneStatus.Released) {
                allReleased = false;
                break;
            }
        }

        if (allReleased && deal.releasedAmount == deal.totalAmount) {
            deal.status = DealStatus.Completed;
            deal.completedAt = block.timestamp;
            emit DealCompleted(_dealIndex, block.timestamp);
        }
    }

    // =============================================================================
    // DISPUTE RESOLUTION
    // =============================================================================

    function initiateDispute(
        uint256 _dealIndex,
        string calldata _reason,
        uint256 _claimedAmount
    ) 
        external 
        dealExists(_dealIndex)
        onlyDealParty(_dealIndex)
    {
        Deal storage deal = deals[_dealIndex];
        require(
            deal.status == DealStatus.Funded || 
            deal.status == DealStatus.InProgress,
            "Cannot dispute"
        );
        require(disputes[_dealIndex].filedAt == 0, "Dispute exists");

        deal.status = DealStatus.Disputed;
        deal.disputeDeadline = block.timestamp + disputeResolutionPeriod;

        disputes[_dealIndex] = Dispute({
            dealIndex: _dealIndex,
            initiator: msg.sender,
            reason: _reason,
            claimedAmount: _claimedAmount,
            filedAt: block.timestamp,
            resolvedAt: 0,
            resolver: address(0),
            resolved: false,
            resolution: ""
        });

        emit DisputeInitiated(_dealIndex, msg.sender, _reason);
    }

    function resolveDispute(
        uint256 _dealIndex,
        uint256 _buyerAmount,
        uint256 _sellerAmount,
        string calldata _resolution
    ) 
        external 
        nonReentrant
        onlyRole(ARBITER_ROLE)
        dealExists(_dealIndex)
        inStatus(_dealIndex, DealStatus.Disputed)
    {
        Deal storage deal = deals[_dealIndex];
        Dispute storage dispute = disputes[_dealIndex];
        
        require(!dispute.resolved, "Already resolved");
        
        uint256 remainingFunds = deal.depositedAmount - deal.releasedAmount;
        require(_buyerAmount + _sellerAmount <= remainingFunds, "Exceeds funds");

        IERC20 token = IERC20(deal.paymentToken);

        if (_buyerAmount > 0) {
            token.safeTransfer(deal.buyer, _buyerAmount);
            deal.refundedAmount += _buyerAmount;
        }

        if (_sellerAmount > 0) {
            token.safeTransfer(deal.seller, _sellerAmount);
            deal.releasedAmount += _sellerAmount;
        }

        dispute.resolved = true;
        dispute.resolvedAt = block.timestamp;
        dispute.resolver = msg.sender;
        dispute.resolution = _resolution;

        // Update deal status
        if (deal.refundedAmount == deal.depositedAmount) {
            deal.status = DealStatus.Refunded;
        } else if (deal.releasedAmount == deal.totalAmount) {
            deal.status = DealStatus.Completed;
            deal.completedAt = block.timestamp;
        } else {
            deal.status = DealStatus.InProgress;
        }

        emit DisputeResolved(_dealIndex, msg.sender, _resolution);
    }

    // =============================================================================
    // CANCELLATION & REFUND
    // =============================================================================

    function cancelDeal(uint256 _dealIndex, string calldata _reason) 
        external 
        nonReentrant
        dealExists(_dealIndex)
    {
        Deal storage deal = deals[_dealIndex];
        
        // Only allow cancellation in certain states
        require(
            deal.status == DealStatus.Created ||
            (deal.status == DealStatus.Funded && msg.sender == deal.seller),
            "Cannot cancel"
        );
        
        require(
            msg.sender == deal.buyer || 
            msg.sender == deal.seller ||
            hasRole(PLATFORM_ADMIN, msg.sender),
            "Not authorized"
        );

        // Refund if funded
        if (deal.depositedAmount > deal.releasedAmount) {
            uint256 refundAmount = deal.depositedAmount - deal.releasedAmount;
            IERC20(deal.paymentToken).safeTransfer(deal.buyer, refundAmount);
            deal.refundedAmount = refundAmount;
            emit FundsRefunded(_dealIndex, refundAmount, deal.buyer);
        }

        deal.status = DealStatus.Cancelled;
        emit DealCancelled(_dealIndex, _reason);
    }

    // =============================================================================
    // VIEW FUNCTIONS
    // =============================================================================

    function getDeal(uint256 _dealIndex) 
        external 
        view 
        returns (Deal memory) 
    {
        return deals[_dealIndex];
    }

    function getDealMilestones(uint256 _dealIndex) 
        external 
        view 
        returns (Milestone[] memory) 
    {
        return dealMilestones[_dealIndex];
    }

    function getDispute(uint256 _dealIndex) 
        external 
        view 
        returns (Dispute memory) 
    {
        return disputes[_dealIndex];
    }

    function getDealCount() external view returns (uint256) {
        return deals.length;
    }

    function getBuyerDeals(address _buyer) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return buyerDeals[_buyer];
    }

    function getSellerDeals(address _seller) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return sellerDeals[_seller];
    }

    function getDealByDealId(string calldata _dealId) 
        external 
        view 
        returns (Deal memory, uint256) 
    {
        uint256 index = dealIdToIndex[_dealId];
        require(index < deals.length || deals.length == 0, "Deal not found");
        return (deals[index], index);
    }
}

